body:
// 緩和項の計算
// 緩和係数(gamma)を用いて前回ΣD値を減衰させる
D_relax = prev_SigmaD * gamma;

// 発生項の計算
// 最新D値、温度に依存する定数、および発生項の寄与分(eta)を基に、新規の濃度偏り発生分を算出する
D_generation = latest_D + eta_function(temperature);

// 今回のΣD値の算出と更新
// 前回値から緩和項を引き、発生項を加算する
current_SigmaD = prev_SigmaD - D_relax + D_generation;

// 負値クリップ処理 (塩濃度偏りは最小0に制限)
if (current_SigmaD < 0) {
    current_SigmaD = 0;
}
